Exercice interactif — Quiz de dérivation
Testez vos reflexes : une fonction s’affiche, choisissez la bonne dérivée et recevez un retour immédiat.
#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| components: [viewer]
#| viewerHeight: 430

from shiny import App, render, ui, reactive
import random

BG = '#1C2E22'
FG = '#D2CCC0'

QUESTIONS = [
    {
        "func":    "f(x) = 5",
        "correct": "f'(x) = 0",
        "choices": ["f'(x) = 0", "f'(x) = 5", "f'(x) = 1", "f'(x) = 5x"],
        "hint":    "La dérivée d'une constante est toujours zéro.",
        "rule":    "Constante",
    },
    {
        "func":    "f(x) = 3x",
        "correct": "f'(x) = 3",
        "choices": ["f'(x) = 3x²", "f'(x) = 3", "f'(x) = x", "f'(x) = 1/3"],
        "hint":    "La dérivée de kx est k : c'est la pente de la droite.",
        "rule":    "Linéaire",
    },
    {
        "func":    "f(x) = x⁴",
        "correct": "f'(x) = 4x³",
        "choices": ["f'(x) = 4x⁵", "f'(x) = x³", "f'(x) = 4x³", "f'(x) = 4"],
        "hint":    "Règle puissance : (xⁿ)' = n·xⁿ⁻¹. Ici n=4.",
        "rule":    "Puissance",
    },
    {
        "func":    "f(x) = eˣ",
        "correct": "f'(x) = eˣ",
        "choices": ["f'(x) = eˣ⁻¹", "f'(x) = x·eˣ", "f'(x) = eˣ", "f'(x) = 1"],
        "hint":    "L'exponentielle est sa propre dérivée : (eˣ)' = eˣ.",
        "rule":    "Exponentielle",
    },
    {
        "func":    "f(x) = ln(x)",
        "correct": "f'(x) = 1/x",
        "choices": ["f'(x) = 1/x", "f'(x) = x", "f'(x) = ln(x)/x", "f'(x) = eˣ"],
        "hint":    "(ln x)' = 1/x, valable pour x &gt; 0.",
        "rule":    "Logarithme",
    },
    {
        "func":    "f(x) = e^(3x)",
        "correct": "f'(x) = 3e^(3x)",
        "choices": ["f'(x) = e^(3x)", "f'(x) = 3e^(3x)", "f'(x) = 3xe^(3x)", "f'(x) = e^(3)"],
        "hint":    "Exponentielle composée : (e^u)' = u'·e^u. Ici u=3x donc u'=3.",
        "rule":    "Exp. composée",
    },
    {
        "func":    "f(x) = ln(2x² + 1)",
        "correct": "f'(x) = 4x / (2x² + 1)",
        "choices": [
            "f'(x) = 1 / (2x² + 1)",
            "f'(x) = 4x / (2x² + 1)",
            "f'(x) = 4x · ln(2x² + 1)",
            "f'(x) = 2x / (2x² + 1)",
        ],
        "hint":    "Log. compose : (ln u)' = u'/u. Ici u=2x²+1 donc u'=4x.",
        "rule":    "Log. compose",
    },
    {
        "func":    "f(x) = (2x + 3)·eˣ",
        "correct": "f'(x) = (2x + 5)·eˣ",
        "choices": [
            "f'(x) = 2·eˣ",
            "f'(x) = (2x + 3)·eˣ",
            "f'(x) = (2x + 5)·eˣ",
            "f'(x) = 2(x + 3)·eˣ",
        ],
        "hint":    "Règle du produit : (uv)' = u'v + uv'. Ici u=2x+3, v=eˣ.",
        "rule":    "Produit",
    },
]

# Randomise once at startup
_order = list(range(len(QUESTIONS)))
random.shuffle(_order)

app_ui = ui.page_fluid(
    ui.tags.style(f"""
        body {{ background-color:{BG}; color:{FG}; padding:14px;
                font-family:sans-serif; margin:0; }}
        .btn-choice {{
            display:block; width:100%; margin:5px 0;
            background:#152119; color:{FG};
            border:1px solid #2F4636; border-radius:6px;
            padding:8px 14px; cursor:pointer; font-size:0.9em;
            text-align:left;
        }}
        .btn-choice:hover {{ background:#253A2C; }}
        .feedback {{ border-radius:6px; padding:10px 14px; margin-top:10px;
                     font-size:0.9em; }}
        .correct  {{ background:#1a3a1a; border-left:4px solid #4caf50; }}
        .wrong    {{ background:#3a1a1a; border-left:4px solid #e53935; }}
        .score    {{ font-size:0.85em; color:#aaa; margin-bottom:6px; }}
        .rule-tag {{ font-size:0.75em; color:#888; margin-bottom:8px; }}
    """),
    ui.h5("🧠 Quiz — Quelle est la dérivée ?", style=f"color:{FG}"),
    ui.output_ui("score_line"),
    ui.output_ui("question_ui"),
    ui.output_ui("feedback_ui"),
    ui.div(
        ui.input_action_button("next_q", "Question suivante →",
                               style="margin-top:10px; background:#253A2C; "
                                     "color:#D2CCC0; border:1px solid #2F4636; "
                                     "border-radius:6px; padding:7px 18px; cursor:pointer;"),
    ),
)

def server(input, output, session):
    idx        = reactive.Value(0)
    answered   = reactive.Value(False)
    chosen     = reactive.Value(None)
    score      = reactive.Value(0)
    total_done = reactive.Value(0)

    def current_q():
        return QUESTIONS[_order[idx() % len(_order)]]

    @output
    @render.ui
    def score_line():
        done = total_done()
        if done == 0:
            return ui.p("Répondez aux questions pour voir votre score.",
                        class_="score")
        pct = round(100 * score() / done)
        return ui.HTML(
            f"&lt;p class='score'&gt;Score : {score()} / {done} ({pct}%)&lt;/p&gt;"
        )

    @output
    @render.ui
    def question_ui():
        q = current_q()
        choices_html = "".join(
            f"&lt;button class='btn-choice' onclick=\"Shiny.setInputValue('choice','{c}',{{priority:'event'}})\"&gt;{c}&lt;/button&gt;"
            for c in q["choices"]
        )
        return ui.HTML(
            f"&lt;p class='rule-tag'&gt;Règle : {q['rule']}&lt;/p&gt;"
            f"&lt;p&gt;&lt;strong&gt;Donnez la dérivée de&lt;/strong&gt; &nbsp; "
            f"&lt;code style='font-size:1em;'&gt;{q['func']}&lt;/code&gt;&lt;/p&gt;"
            + choices_html
        )

    @output
    @render.ui
    def feedback_ui():
        if not answered():
            return ui.HTML("")
        q = current_q()
        if chosen() == q["correct"]:
            return ui.HTML(
                f"&lt;div class='feedback correct'&gt;"
                f"✅ &lt;strong&gt;Correct !&lt;/strong&gt;&lt;br&gt;{q['hint']}&lt;/div&gt;"
            )
        return ui.HTML(
            f"&lt;div class='feedback wrong'&gt;"
            f"❌ &lt;strong&gt;Incorrect.&lt;/strong&gt; Bonne réponse : "
            f"&lt;em&gt;{q['correct']}&lt;/em&gt;&lt;br&gt;{q['hint']}&lt;/div&gt;"
        )

    @reactive.Effect
    @reactive.event(input.choice)
    def _on_choice():
        if answered():
            return
        c = input.choice()
        q = current_q()
        answered.set(True)
        chosen.set(c)
        total_done.set(total_done() + 1)
        if c == q["correct"]:
            score.set(score() + 1)

    @reactive.Effect
    @reactive.event(input.next_q)
    def _on_next():
        idx.set(idx() + 1)
        answered.set(False)
        chosen.set(None)

app = App(app_ui, server)

Interactive demo — central tendency & dispersion calculator
Move the six sliders below and watch the mean, variance, standard deviation, and coefficient of variation update live. Starting values are a 6-day sample of “The Wandering Fork”’s daily_revenue_eur.

viewof days = {
  const start = [460.48, 500.02, 418.65, 785.79, 719.66, 886.56];
  const form = html`&lt;form class="ojs-calculator"&gt;${start.map((v, i) =&gt;
    html`&lt;div&gt;&lt;label&gt;Day ${i + 1} (€):
      &lt;input type="range" min="300" max="950" step="0.01" value="${v}"&gt;
      &lt;output&gt;${v.toFixed(2)}&lt;/output&gt;&lt;/label&gt;&lt;/div&gt;`)}&lt;/form&gt;`;
  const inputs = [...form.querySelectorAll("input")];
  const outs = [...form.querySelectorAll("output")];
  form.value = start.slice();
  form.oninput = () =&gt; {
    form.value = inputs.map(el =&gt; el.valueAsNumber);
    outs.forEach((o, i) =&gt; { o.textContent = form.value[i].toFixed(2); });
  };
  return form;
}







calc = {
  const n = days.length;
  const mean = days.reduce((a, b) =&gt; a + b, 0) / n;
  const sorted = [...days].sort((a, b) =&gt; a - b);
  const median = (sorted[n / 2 - 1] + sorted[n / 2]) / 2;
  const s2 = days.reduce((a, x) =&gt; a + (x - mean) ** 2, 0) / (n - 1);
  const s = Math.sqrt(s2);
  return {n, mean, median, s2, s, cv: mean ? s / mean * 100 : 0};
}

html`&lt;p&gt;&lt;strong&gt;Mean&lt;/strong&gt; = ${calc.mean.toFixed(2)} ·
  &lt;strong&gt;Median&lt;/strong&gt; = ${calc.median.toFixed(2)}&lt;br&gt;
  &lt;strong&gt;Variance&lt;/strong&gt; s² = ${calc.s2.toFixed(2)} ·
  &lt;strong&gt;Std. dev.&lt;/strong&gt; s = ${calc.s.toFixed(2)} ·
  &lt;strong&gt;CV&lt;/strong&gt; = ${calc.cv.toFixed(2)}%&lt;/p&gt;`
















{
  const W = 660, H = 300, L = 60, R = 20, T = 30, B = 40;
  const x = d =&gt; L + (d - 0.5) * (W - L - R) / 6;
  const y = v =&gt; T + (950 - v) * (H - T - B) / (950 - 300);
  let g = "";
  for (let v = 300; v &lt;= 900; v += 100) {
    g += `&lt;line x1="${L}" x2="${W - R}" y1="${y(v)}" y2="${y(v)}"
      stroke="currentColor" stroke-opacity="0.15"/&gt;`;
    g += `&lt;text x="${L - 8}" y="${y(v) + 4}" text-anchor="end"
      fill="currentColor" font-size="12"&gt;€${v}&lt;/text&gt;`;
  }
  days.forEach((v, i) =&gt; {
    g += `&lt;line x1="${x(i + 1)}" x2="${x(i + 1)}" y1="${y(calc.mean)}"
      y2="${y(v)}" stroke="currentColor" stroke-opacity="0.5"/&gt;`;
    g += `&lt;circle cx="${x(i + 1)}" cy="${y(v)}" r="7" fill="steelblue"/&gt;`;
    g += `&lt;text x="${x(i + 1)}" y="${H - 15}" text-anchor="middle"
      fill="currentColor" font-size="12"&gt;Day ${i + 1}&lt;/text&gt;`;
  });
  g += `&lt;line x1="${L}" x2="${W - R}" y1="${y(calc.mean)}" y2="${y(calc.mean)}"
    stroke="darkorange" stroke-width="2" stroke-dasharray="6 4"/&gt;`;
  g += `&lt;text x="${W - R}" y="${y(calc.mean) - 6}" text-anchor="end"
    fill="darkorange" font-size="12"&gt;mean = ${calc.mean.toFixed(2)}&lt;/text&gt;`;
  g += `&lt;text x="${W / 2}" y="18" text-anchor="middle" fill="currentColor"
    font-size="14"&gt;Deviations from the mean&lt;/text&gt;`;
  return html`&lt;svg viewBox="0 0 ${W} ${H}" width="100%" role="img"
    aria-label="Six daily revenues and their deviations from the mean"&gt;
    ${g}&lt;/svg&gt;`;
}

Exploration interactive
Utilisez le curseur pour choisir une quantité produite \(q\) et observer l’évolution du chiffre d’affaires, du coût et du profit. La droite pointillée rouge marque l’optimum \(q^* = 100\) obtenu analytiquement.

viewof quantity = Inputs.range([0, 200], {
  value: 50,
  step: 1,
  label: "Quantité q (unités)"
})







qRange = Array.from({length: 201}, (_, i) =&gt; i)
curveData = qRange.flatMap(q =&gt; [
  {q, value: 60*q - 0.2*q*q, curve: "Chiffre d'affaires R(q)"},
  {q, value: 500 + 20*q, curve: "Coût C(q)"},
  {q, value: 60*q - 0.2*q*q - 500 - 20*q, curve: "Profit P(q)"}
])

qStar = 100
revenue_q = 60*quantity - 0.2*quantity*quantity
cost_q = 500 + 20*quantity
profit_q = revenue_q - cost_q
revenue_opt = 60*qStar - 0.2*qStar*qStar
profit_opt = revenue_opt - (500 + 20*qStar)

profitChart = Plot.plot({
  marks: [
    Plot.line(curveData, {x: "q", y: "value", stroke: "curve"}),
    Plot.ruleY([0], {stroke: "#aaa", strokeDash: [2,2]}),
    Plot.ruleX([quantity], {stroke: "white", strokeDash: [3,3]}),
    Plot.ruleX([qStar], {stroke: "red", strokeDash: [4,2]})
  ],
  x: {label: "Quantité q"},
  y: {label: "Valeur (€)"},
  color: {legend: true},
  width: 550,
  height: 320
})

































































html`
&lt;div style="margin-bottom:1rem"&gt;${profitChart}&lt;/div&gt;
&lt;p style="font-size:0.85rem;opacity:0.7"&gt;Droite pointillée blanche : votre
position q = ${quantity}. Droite pointillée rouge : optimum q* = 100.&lt;/p&gt;
&lt;div class="metric-grid"&gt;
  &lt;div class="metric-card"&gt;
    &lt;span class="metric-label"&gt;Chiffre d'affaires R(q)&lt;/span&gt;
    &lt;strong&gt;${revenue_q.toFixed(0)} €&lt;/strong&gt;
  &lt;/div&gt;
